"""Checkpoint11 reviewed patch; only for the isolated test branch."""
import base64, hashlib, subprocess, zlib
PATCH = zlib.decompress(base64.b64decode(""))
assert hashlib.sha256(PATCH).hexdigest() == "f8014b30747895500bacf54c1b6a99b062b1723a2fc53c3fb2a32ae21f480ef4"
subprocess.run(["git", "merge-base", "--is-ancestor", "9759bbee2f829f995119799f305f917f73497835", "HEAD"], check=True)
subprocess.run(["git", "apply", "--check", "-"], input=PATCH, check=True)
subprocess.run(["git", "apply", "-"], input=PATCH, check=True)
